+        };
+
+        var issues = _validator.Validate(graph);
+
+        Assert.Equal(1, issues.Count(x => x.Code == "DuplicateTransitionIdentity" && x.Target == "Pending->Approved" && x.Severity == StateMachineValidationSeverity.Error));
+    }
