+
+        var transitionName = string.IsNullOrWhiteSpace(_newTransitionName)
+            ? GetUniqueTransitionName(_graph)
+            : _newTransitionName.Trim();
+
+        var transition = new StateMachineTransitionEdge
+        {
+            Name = transitionName,
